class MidiSerialEnableTask final {
public:enum class Stage:uint8_t {BindControl,WriteControl,ResetRx,ResetTx,Return,AwaitChild,Complete};enum class Child:uint8_t {ResetRx,ResetTx};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaitingChild()const{return stage_==Stage::AwaitChild;}Child child()const{return child_;}bool resume(Child c){if(!awaitingChild()||child_!=c)return false;stage_=c==Child::ResetRx?Stage::ResetTx:Stage::Return;return true;}template<class W>bool advance(W&&w){switch(stage_){case Stage::BindControl:stage_=Stage::WriteControl;break;case Stage::WriteControl:w();stage_=Stage::ResetRx;break;case Stage::ResetRx:child_=Child::ResetRx;stage_=Stage::AwaitChild;break;case Stage::ResetTx:child_=Child::ResetTx;stage_=Stage::AwaitChild;break;case Stage::Return:stage_=Stage::Complete;break;case Stage::AwaitChild:case Stage::Complete:return false;}return true;}private:Stage stage_=Stage::BindControl;Child child_=Child::ResetRx;
};
